"""Export and import of stored files for backups (``scripts/backup.sh`` / ``restore.sh``).

The database is backed up with ``pg_dump``; files live in object storage and are streamed
here as one tar archive (key = path inside the archive), so a backup is two files that can
be copied anywhere. Import restores every object under the same key.
"""

from __future__ import annotations

import tarfile
import tempfile
from typing import BinaryIO

from app.core.storage import ObjectStorage

# Keys are generated by the application (uuid/filename); refuse anything that could escape.
_MAX_KEY = 1024


def _safe_key(name: str) -> str | None:
    """The object key for an archive entry, or None if the name is not one we would write
    (absolute, parent segments, backslashes, empty or too long)."""
    key = name[2:] if name.startswith("./") else name
    if (
        not key
        or len(key) > _MAX_KEY
        or key.startswith("/")
        or "\\" in key
        or any(part in {"", ".", ".."} for part in key.split("/"))
    ):
        return None
    return key


def export_objects(storage: ObjectStorage, out: BinaryIO) -> int:
    """Write every object to ``out`` as a tar stream; returns the number of objects."""
    count = 0
    with tarfile.open(fileobj=out, mode="w|") as archive:
        for obj in storage.iter_objects():
            # Spool to disk so large files never sit in memory.
            with tempfile.TemporaryFile() as tmp:
                storage.download_to(obj.key, tmp)
                info = tarfile.TarInfo(name=obj.key)
                info.size = obj.size
                info.mtime = int(obj.last_modified.timestamp())
                archive.addfile(info, tmp)
            count += 1
    return count


def import_objects(storage: ObjectStorage, source: BinaryIO) -> tuple[int, int]:
    """Restore objects from a tar stream made by :func:`export_objects`.

    Returns (restored, skipped); entries that are not regular files or whose names could
    escape the bucket layout are skipped."""
    restored = skipped = 0
    with tarfile.open(fileobj=source, mode="r|") as archive:
        for member in archive:
            key = _safe_key(member.name)
            data = archive.extractfile(member) if member.isfile() else None
            if key is None or data is None:
                skipped += 1
                continue
            with tempfile.TemporaryFile() as tmp:
                while chunk := data.read(1024 * 1024):
                    tmp.write(chunk)
                tmp.seek(0)
                storage.put_bytes(key, tmp, content_type="application/octet-stream")
            restored += 1
    return restored, skipped
